from itertools import permutations

def adj(i,j):
    return [(a,b) for a,b in [(i-1,j-1),(i-1,j),(i,j-1),(i,j)] if 0<=a<R and 0<=b<Cn]

corners=[(i,j) for i in range(R+1) for j in range(Cn+1)]

def solve(rule):
    sols=[]
    O={}
    cells=[(a,b) for a in range(R) for b in range(Cn)]
    def corner_val(i,j,O):
        vals=[O.get(p) for p in adj(i,j)]
        return rule(vals)
    def consistent(O):
        # only check corners whose adjacent cells are all assigned
        for (i,j) in corners:
            ps=adj(i,j)
            if all(p in O for p in ps):
                if corner_val(i,j,O)!=C[i,j]: return False
        return True
    def dfs(idx):
        if len(sols)>3: return
        if idx==len(cells):
            if consistent(O): sols.append(dict(O))
            return
        p=cells[idx]
        for v in (FILL,4,6):
            O[p]=v
            if consistent(O): dfs(idx+1)
            del O[p]
    dfs(0)
    return sols

